import React from "react";
import "./App.css";

const menuItems = [
  ["🛒", "New order"],
  ["◉", "Announcement group"],
  ["▣", "Services"],
  ["▣", "Orders"],
  ["▱", "Add funds"],
  ["⚒", "API"],
  ["♧", "Affiliates"],
  ["♟", "Child panel"],
  ["▰", "Tickets"],
  ["♧", "Mass order"],
  ["🔧", "Updates"],
];

function QRCode() {
  // Visual placeholder styled like the QR code in the screenshot.
  // Replace with qrcode.react if you need a real scannable QR.
  const blocks = Array.from({ length: 225 });

  return (
    <div className="qr-wrapper">
      <div className="qr-code">
        {blocks.map((_, i) => {
          const x = i % 15;
          const y = Math.floor(i / 15);

          const finder =
            (x < 5 && y < 5) ||
            (x > 9 && y < 5) ||
            (x < 5 && y > 9);

          const innerFinder =
            (x === 1 && y === 1) ||
            (x === 3 && y === 1) ||
            (x === 1 && y === 3) ||
            (x === 3 && y === 3) ||
            (x === 11 && y === 1) ||
            (x === 13 && y === 1) ||
            (x === 11 && y === 3) ||
            (x === 13 && y === 3) ||
            (x === 1 && y === 11) ||
            (x === 3 && y === 11) ||
            (x === 1 && y === 13) ||
            (x === 3 && y === 13);

          const randomBlock =
            ((x * 17 + y * 31 + x * y * 7) % 11) < 5;

          return (
            <span
              key={i}
              className={
                finder
                  ? innerFinder
                    ? "qr-black"
                    : "qr-white"
                  : randomBlock
                  ? "qr-black"
                  : "qr-white"
              }
            />
          );
        })}
      </div>

      <div className="upi-text">UPI ID: paytm.s2424z4@pty</div>
    </div>
  );
}

function Sidebar() {
  return (
    <aside className="sidebar">
      <div className="logo">
        <div className="logo-circle">
          <span>◉</span>
        </div>
        <div className="logo-text">
          <strong>GROWW</strong>
          <strong>SMM</strong>
        </div>
      </div>

      <nav>
        {menuItems.map(([icon, label]) => (
          <div
            key={label}
            className={`menu-item ${label === "Add funds" ? "active" : ""}`}
          >
            <span className="menu-icon">{icon}</span>
            <span>{label}</span>
          </div>
        ))}
      </nav>
    </aside>
  );
}

function PaymentCard() {
  return (
    <section className="payment-card">
      <div className="field">
        <label>Method</label>
        <div className="select">
          Phone pe [ Min 50 ] [ Ankur Justin Xess ]
          <span>⌄</span>
        </div>
      </div>

      <div className="field">
        <label>Order ID</label>
        <input />
      </div>

      <div className="field">
        <label>Amount</label>
        <input />
      </div>

      <div className="instruction">
        <label>Instruction</label>

        <div className="instruction-content">
          <div className="changed">
            Qr Changed Please scan before payment
          </div>

          <QRCode />

          <div className="only-phone">Only PhonePe</div>

          <p className="note">
            Note: Don't Ask Third party payment on this QR code otherwise your
            account will be suspend.
          </p>
        </div>
      </div>

      <button className="check-button">Check</button>
    </section>
  );
}

function Transactions() {
  return (
    <section className="transactions">
      <div className="table-header">
        <span>ID</span>
        <span>Date</span>
        <span>Method</span>
        <span>Amount</span>
        <span></span>
      </div>

      <div className="table-row">
        <span>325057</span>
        <span>2026-09-06 11:00:51</span>
        <span>Phone pe [ Min 50 ] [ Ankur Justin Xess ]</span>
        <span>10.00</span>
        <button>Download invoice</button>
      </div>
    </section>
  );
}

function App() {
  return (
    <div className="app">
      <Sidebar />

      <main className="main">
        <PaymentCard />
        <Transactions />
      </main>

      <button className="whatsapp">◔</button>
    </div>
  );
}

export default App;
